 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The 7-colored shape is a pattern. Locate other background-colored
    # occurrences of that shape and paint their pattern cells with 7.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 7]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    motif = {(r-r0, c-c0) for r, c in pts}
    mh, mw = r1-r0+1, c1-c0+1
    out = [row[:] for row in grid]
    for r in range(h-mh+1):
        for c in range(w-mw+1):
            if (r, c) == (r0, c0):
                continue
            if all(grid[r+dr][c+dc] == 0 for dr, dc in motif):
                for dr, dc in motif:
                    out[r+dr][c+dc] = 7
    return out
